WITH catalog_daily AS ( SELECT cs.cs_sold_date_sk AS date_sk, SUM(cs.cs_net_profit) AS catalog_profit, SUM(cs.cs_ext_sales_price) AS catalog_sales FROM catalog_sales cs GROUP BY cs.cs_sold_date_sk ), web_daily AS ( SELECT ws.ws_sold_date_sk AS date_sk, SUM(ws.ws_net_profit) AS web_profit, SUM(ws.ws_ext_sales_price) AS web_sales FROM web_sales ws GROUP BY ws.ws_sold_date_sk ), combined_daily AS ( SELECT d.d_date AS sale_date, d.d_weekend, COALESCE(c.catalog_profit, 0) AS catalog_profit, COALESCE(w.web_profit, 0) AS web_profit, COALESCE(c.catalog_sales, 0) AS catalog_sales, COALESCE(w.web_sales, 0) AS web_sales, (COALESCE(c.catalog_profit, 0) + COALESCE(w.web_profit, 0)) AS total_profit, (COALESCE(c.catalog_sales, 0) + COALESCE(w.web_sales, 0)) AS total_sales FROM date_dim d LEFT JOIN catalog_daily c ON d.d_date_sk = c.date_sk LEFT JOIN web_daily w ON d.d_date_sk = w.date_sk WHERE d.d_weekend = 'Y' ) SELECT sale_date, total_profit, total_sales, CASE WHEN total_profit > 100000 THEN 'Very High' WHEN total_profit > 50000 THEN 'High' WHEN total_profit > 10000 THEN 'Medium' ELSE 'Low' END AS profit_category, catalog_profit / NULLIF(total_profit, 0) AS catalog_profit_share, web_profit / NULLIF(total_profit, 0) AS web_profit_share, RANK() OVER (ORDER BY total_profit DESC) AS profit_rank, SUM(total_profit) OVER (ORDER BY sale_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_profit FROM combined_daily ORDER BY profit_rank FETCH FIRST 10 ROWS ONLY
